<?php
namespace App\Services\Marketing;
use App\Models\{MarketingPost,MarketingCampaign,Order};use Illuminate\Support\Facades\{DB,Crypt};use Illuminate\Support\Str;use Illuminate\Http\Request;
class MarketingAttribution {
 public function enabled():bool{return (bool)config('marketing.attribution_enabled',false);}
 public function createLink(int $user,string $post,string $destination,int $version):array{return app(MarketingTrackingPreparation::class)->prepare($user,$post,$destination,$version);}
 public function link(string $id){return DB::table('marketing_tracking_links')->where('merchant_key',app(MarketingPosts::class)->merchant())->where('id',$id)->first();}
 public function arrival(Request $r,string $token):bool{if(!$this->enabled()||$r->session()->get('marketing.consent')!==true||!$this->qualifiedRequest($r))return false;$d=json_decode(Crypt::decryptString($token),true,16,JSON_THROW_ON_ERROR);abort_unless(is_array($d)&&isset($d['id'],$d['at'])&&is_int($d['at'])&&$d['at']<=now()->timestamp+30&&$d['at']>=now()->subDays(7)->timestamp,422,'This campaign link has expired.');$link=$this->link($d['id']);abort_unless($link,404);$sid=$this->activeSession($r,false);$touch=['id'=>$link->id,'at'=>$d['at'],'session'=>$sid];$prior=$r->session()->get('marketing.last');if(!$prior||$d['at']>$prior['at'])$r->session()->put('marketing.last',$touch);if(!$r->session()->has('marketing.first')||$r->session()->get('marketing.first.at')<now()->subDays(7)->timestamp)$r->session()->put('marketing.first',$touch);DB::table('marketing_analytics_events')->insertOrIgnore(['merchant_key'=>$link->merchant_key,'campaign_id'=>$link->campaign_id,'link_id'=>$link->id,'kind'=>'arrival','session_key'=>$sid,'dedupe_key'=>'arrival:'.$link->id.':'.$sid,'occurred_at'=>now()]);return true;}
 public function checkout(Request $r):void{if(!$this->enabled()||$r->session()->get('marketing.consent')!==true)return;$this->activeSession($r);$t=$r->session()->get('marketing.last');if(!$t||$t['at']<now()->subDays(7)->timestamp)return;$l=$this->link($t['id']);if(!$l)return;$attempt=$r->session()->get('marketing.checkout');if(!$attempt){$attempt=(string)Str::uuid();$r->session()->put('marketing.checkout',$attempt);$r->session()->put('marketing.checkout_touch',$t);}DB::table('marketing_analytics_events')->insertOrIgnore(['merchant_key'=>$l->merchant_key,'campaign_id'=>$l->campaign_id,'link_id'=>$l->id,'kind'=>'checkout','session_key'=>$t['session'],'dedupe_key'=>'checkout:'.$attempt,'occurred_at'=>now()]);}
 public function attach(Order $o,Request $r):void{if(!$this->enabled()||!$r->hasSession()||$r->session()->get('marketing.consent')!==true)return;$this->activeSession($r);$t=$r->session()->get('marketing.checkout_touch')??$r->session()->get('marketing.last');if(!$t||$t['at']<now()->subDays(7)->timestamp)return;$l=$this->link($t['id']);if(!$l)return;$base=collect(app(\App\Support\CurrencySettings::class)->all())->filter(fn($c)=>(float)$c['exchangeRate']===1.0)->values();$currency=$base->count()===1?$base[0]['code']:null;if($o->shipping_method==='quoted_manual')$currency=$o->currency;DB::table('marketing_order_attributions')->insertOrIgnore(['order_id'=>$o->id,'merchant_key'=>$l->merchant_key,'campaign_id'=>$l->campaign_id,'link_id'=>$l->id,'first_link_id'=>$r->session()->get('marketing.first.id'),'owner_id'=>$l->user_id,'session_key'=>$t['session'],'clicked_at'=>date('Y-m-d H:i:s',$t['at']),'placed_at'=>now(),'base_currency'=>$currency,'base_minor'=>$o->total,'state'=>$currency?'pending':'money_unconfirmed','created_at'=>now(),'updated_at'=>now()]);$r->session()->forget(['marketing.checkout','marketing.checkout_touch']);}
 public function attachEnquiry(\App\Models\ProductEnquiry $e,Request $r):void{if(!$this->enabled()||$r->session()->get('marketing.consent')!==true)return;$this->activeSession($r);$t=$r->session()->get('marketing.last');if(!$t||$t['at']<now()->subDays(7)->timestamp||$t['at']>now()->timestamp+30)return;$l=$this->link($t['id']);if(!$l)return;DB::table('marketing_enquiry_attributions')->insertOrIgnore(['enquiry_id'=>$e->id,'merchant_key'=>$l->merchant_key,'campaign_id'=>$l->campaign_id,'link_id'=>$l->id,'first_link_id'=>$r->session()->get('marketing.first.id'),'owner_id'=>$l->user_id,'session_key'=>$t['session'],'clicked_at'=>date('Y-m-d H:i:s',$t['at']),'submitted_at'=>$e->created_at,'created_at'=>now(),'updated_at'=>now()]);}
 public function inheritEnquiry(Order $o,string $enquiry):void{$a=DB::table('marketing_enquiry_attributions')->where('merchant_key',app(MarketingPosts::class)->merchant())->where('enquiry_id',$enquiry)->first();if(!$a)return;DB::table('marketing_order_attributions')->insertOrIgnore(['order_id'=>$o->id,'merchant_key'=>$a->merchant_key,'campaign_id'=>$a->campaign_id,'link_id'=>$a->link_id,'first_link_id'=>$a->first_link_id,'owner_id'=>$a->owner_id,'session_key'=>$a->session_key,'clicked_at'=>$a->clicked_at,'placed_at'=>now(),'policy'=>'enquiry-source-v1','base_currency'=>$o->currency,'base_minor'=>$o->total,'state'=>'pending','created_at'=>now(),'updated_at'=>now()]);}
 public function websiteEvent(Request $r,string $kind,string $key,array $details=[]):bool{if(!$this->enabled()||!$r->hasSession()||$r->session()->get('marketing.consent')!==true||!$this->qualifiedRequest($r))return false;$this->activeSession($r);$t=$r->session()->get('marketing.last');if(!$t||$t['at']<now()->subDays(7)->timestamp||$t['at']>now()->timestamp+30)return false;$l=$this->link($t['id']);if(!$l)return false;DB::table('marketing_analytics_events')->insertOrIgnore(['merchant_key'=>$l->merchant_key,'campaign_id'=>$l->campaign_id,'link_id'=>$l->id,'kind'=>$kind,'session_key'=>$t['session'],'dedupe_key'=>$kind.':'.hash('sha256',$t['session'].':'.$key),'details'=>json_encode($details),'occurred_at'=>now()]);return true;}
 public function enquiryStage(string $enquiry,string $kind,string $key):void{$a=DB::table('marketing_enquiry_attributions')->where('enquiry_id',$enquiry)->where('merchant_key',app(MarketingPosts::class)->merchant())->first();if(!$a)return;DB::table('marketing_analytics_events')->insertOrIgnore(['merchant_key'=>$a->merchant_key,'campaign_id'=>$a->campaign_id,'link_id'=>$a->link_id,'kind'=>$kind,'session_key'=>$a->session_key,'dedupe_key'=>$kind.':'.$key,'details'=>json_encode(['enquiry_id'=>$enquiry]),'occurred_at'=>now()]);}
 private function qualifiedRequest(Request $r):bool{return !$r->user()?->is_admin&&!preg_match('/bot|crawler|spider|facebookexternalhit|slack-linkexpanding|twitterbot|linkedinbot|discordbot/i',(string)$r->userAgent());}
 private function activeSession(Request $r,bool $recordVisit=true):string{$now=now()->timestamp;$sid=$r->session()->get('marketing.sid');$activity=$r->session()->get('marketing.activity');if(!$sid||!is_int($activity)||$activity<=$now-1800){$sid=hash('sha256',Str::random(40));$r->session()->put('marketing.sid',$sid);$r->session()->forget(['marketing.checkout','marketing.checkout_touch']);$last=$r->session()->get('marketing.last');if(is_array($last)){$last['session']=$sid;$r->session()->put('marketing.last',$last);}}$r->session()->put('marketing.activity',$now);$last=$r->session()->get('marketing.last');if($recordVisit&&$r->session()->get('marketing.consent')===true&&$this->qualifiedRequest($r)&&is_array($last)&&($last['at']??0)>=$now-604800&&($last['at']??0)<=$now+30){$link=$this->link($last['id']);if($link)DB::table('marketing_analytics_events')->insertOrIgnore(['merchant_key'=>$link->merchant_key,'campaign_id'=>$link->campaign_id,'link_id'=>$link->id,'kind'=>'arrival','session_key'=>$sid,'dedupe_key'=>'arrival:'.$link->id.':'.$sid,'occurred_at'=>now()]);}return $sid;}
}
